+using Microsoft.ML;
+using TicketClassifier.Models;
+
+namespace TicketClassifier.Services;
+
+public class TicketModelService
+{
+    private readonly MLContext _mlContext;
+    private readonly ILogger<TicketModelService> _logger;
+    private readonly string _modelPath;
+    private readonly string _dataPath;
+
+    public TicketModelService(ILogger<TicketModelService> logger, IWebHostEnvironment env)
+    {
+        _mlContext = new MLContext(seed: 42);
+        _logger = logger;
+        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
+        _modelPath = Path.Combine(env.ContentRootPath, "Data", "ticket_model.zip");
+    }
+
+    public TrainingMetrics TrainAndEvaluate()
+    {
+        var data = _mlContext.Data.LoadFromTextFile<TicketInput>(
+            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
+
+        var split = _mlContext.Data.TrainTestSplit(data, testFraction: 0.2, seed: 42);
+
+        var pipeline = _mlContext.Transforms.Text.FeaturizeText(
+                "SubjectFeatures", nameof(TicketInput.Subject))
+            .Append(_mlContext.Transforms.Text.FeaturizeText(
+                "DescriptionFeatures", nameof(TicketInput.Description)))
+            .Append(_mlContext.Transforms.Concatenate("Features",
+                "SubjectFeatures", "DescriptionFeatures", nameof(TicketInput.Priority)))
+            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
+            .Append(_mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category)))
+            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy(
+                labelColumnName: "Label", featureColumnName: "Features"))
+            .Append(_mlContext.Transforms.Conversion.MapKeyToValue(
+                "PredictedLabel", "PredictedLabel"));
+
+        var model = pipeline.Fit(split.TrainSet);
+        _mlContext.Model.Save(model, split.TrainSet.Schema, _modelPath);
+
+        var predictions = model.Transform(split.TestSet);
+        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");
+
+        var result = new TrainingMetrics
+        {
+            MicroAccuracy = (float)metrics.MicroAccuracy,
+            MacroAccuracy = (float)metrics.MacroAccuracy,
+            LogLoss = (float)metrics.LogLoss,
+            LogLossReduction = (float)metrics.LogLossReduction,
+        };
+
+        _logger.LogInformation(
+            "Model trained — MicroAccuracy: {Micro:F4}, MacroAccuracy: {Macro:F4}, LogLoss: {LogLoss:F4}",
+            result.MicroAccuracy, result.MacroAccuracy, result.LogLoss);
+
+        return result;
+    }
+
+    public string ModelPath => _modelPath;
+}
+

