/// <summary>Returns the label slot names in Score-array order from the trained model.</summary>
public string[] GetLabelSlotNames()
{
    if (!File.Exists(_modelPath))
        return [];

    var model = _mlContext.Model.Load(_modelPath, out var inputSchema);
    var outputSchema = model.GetOutputSchema(inputSchema);
    var labelCol = outputSchema["Score"];
    var slotNames = new VBuffer<ReadOnlyMemory<char>>();
    labelCol.GetSlotNames(ref slotNames);
    return slotNames.DenseValues().Select(v => v.ToString()).ToArray();
}

